// Enum used to describe keyboard descriptions
enum Direction {
	UP,
	DOWN,
	LEFT,
	RIGHT,
	STILL,
};

// Used to ignore feedback from negative edge (release) of key
bool ignoreNegEdgeKey = false;

void waitForEnterKey() {
	// Read keyboard input
	int PS2_data = *(PS2_ptr); 
		
	// Extract RVALID bit
	int RVALID = PS2_data & 0x8000;

	int keyInput = 0;

	// Wait until enter key is pressed
	while (keyInput != 0x5A) {
		// Read keyboard input
		PS2_data = *(PS2_ptr);

		// Extract RVALID bit
		RVALID = PS2_data & 0x8000;

		// If a key is pressed
		if (RVALID) {
			// Extract key data
			keyInput = PS2_data & 0xFF;
		}
	}
}

// Get the direction input from the keyboard
enum Direction getDirection() {
	// Read keyboard input
	int PS2_data = *(PS2_ptr); 
		
	// Extract RVALID bit
	int RVALID = PS2_data & 0x8000;
	
	// If a key is pressed
	if (RVALID) {
    //Press and release both send PS/2 data. The program must recognize the release sequence so it doesn't 
    // treat the released key's scan code as a new key press.
		if (ignoreNegEdgeKey == true) {
			ignoreNegEdgeKey = false;
			return STILL;
		}

		// Extract key data
		int keyInput = PS2_data & 0xFF;
			
		switch (keyInput) {
			case (0x75):
				return UP;
			case (0x6B):
				return LEFT;
			case (0x74):
				return RIGHT;
			case (0x72):
				return DOWN;
			case (0xF0): {
				ignoreNegEdgeKey = true;
				return STILL;
			}
			default:
				return STILL;
		}
	}

	else {
		return STILL;
	}

}

void setup_and_start_timer_1() {
	// Stop the timer, reset TO bit
	timer_ptr_1->control = 0x8;
	timer_ptr_1->status = 0; 

	// Set the timer to count for a period of 15 secs, or 1.5 billion ticks for this 100MHz clock
	timer_ptr_1->period_high = 0x5968;
	timer_ptr_1->period_low = 0x2F00;

	// Set the timer to a started, continuous, non-interrupt state
	timer_ptr_1->control = 0x6;
}

void setup_and_start_timer_2() {
	// Stop the timer, reset TO bit
	timer_ptr_2->control = 0x8;
	timer_ptr_2->status = 0; 

	// Set the timer to count for period of 1 sec, or 100 million ticks for this 100 MHz clock
	timer_ptr_2->period_high = 0x05F5;
	timer_ptr_2->period_low = 0xE100;

	// Set the timer to a started, continous, non-interrupt state
	timer_ptr_2->control = 0x6;
}

volatile int pixel_buffer_start; // global variable
short int Buffer1[240][512]; // 240 rows, 512 (320 + padding) columns
short int Buffer2[240][512];

// Function that swaps two numbers
void swap(int* num1, int* num2) {
	int temp = *num1;
	*num1 = *num2;
	*num2 = temp;
}

void plot_pixel(int x, int y, short int line_color)
{
    volatile short int *one_pixel_address;
        
        one_pixel_address = pixel_buffer_start + (y << 10) + (x << 1);
        
        *one_pixel_address = line_color;
}

// Function that clears the entire screen (fills it with black)
void clear_screen() {
	for (int x = 0; x < 320; x++) {
		for (int y = 0; y < 240; y++) {
			plot_pixel(x, y, 0x0);
		}
	}
}

